// SPDX-License-Identifier: AGPL-3.0-or-later
// Room: Parents' bedroom (front bedroom, inner air box [9,19,7,18,22,11]; door x17 z12 from the corridor).
// Focal piece: the double bed against the west wall, head to the wall, centred on the room. Nightstands (barrels with
// candle and lantern) either side of the head, a chest barrel at the foot, a wardrobe (bookshelves) in the east corner,
// window boxes (flower pots) under the north windows, a white rug between the bed and the room. Light: two standing
// lanterns/candles at the bed, a hanging lantern centred from the loft floor (y 23).
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { hangLantern } from "../vocab.mjs";

/** Furniture drawn as text: rows run along +x from x 9 (the first column) to x 18, successive rows along +z from z 7. */
const LEGEND = {
  "B": ["red_bed", { facing: "west", part: "head" }],
  "F": ["red_bed", { facing: "west", part: "foot" }],
  "b": ["barrel", { facing: "up", open: "false" }],
  "p": "flower_pot",
  "w": "bookshelf",
  "r": "white_carpet",
  "c": ["candle", { candles: "2", lit: "true" }],
  "L": ["lantern", { hanging: "false" }],
};

// floor level, y 19: bed, nightstands, chest, window boxes, wardrobe foot, rug
const FLOOR = [
  "bkpp...ppw", // z 7: nightstand-chest at x 9..10 corner, window boxes under the north windows, wardrobe
  "...rr....w", // z 8: rug, wardrobe
  "BF.rr.....", // z 9: bed (head at the wall, x 9), foot at x 10, rug
  "...rr.....", // z 10: rug
  "b.........", // z 11: nightstand under the lantern
];

// one block up, y 20: candles on the barrels, lantern on the south nightstand, wardrobe
const SHELF = [
  "cc.......w", // z 7: candles on the nightstand and chest, wardrobe
  ".........w", // z 8: wardrobe
  "..........", // z 9: bed head/foot only, nothing above
  "..........", // z 10
  "L.........", // z 11: lantern on the nightstand
];

// wardrobe top, y 21
const TOP = [
  "..........", // z 7
  ".........w", // z 8 wardrobe top
  "..........", // z 9
  "..........", // z 10
  "..........", // z 11
];

export function build(g) {
  layers(g, [9, 19, 7], LEGEND, [FLOOR, SHELF, TOP]);
  // the hanging lantern centred over the bed-and-rug zone, hung from the loft floor (y 23)
  hangLantern(g, 14, 22, 9);
}

